--
-- Structure for view `customer_finished_goods`
--
DROP TABLE IF EXISTS `customer_finished_goods`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `customer_finished_goods`  AS SELECT `items`.`item_id` AS `item_id`, `items`.`item_code` AS `item_code`, `items`.`item_description` AS `item_description`, `items`.`item_type` AS `item_type`, `items`.`customer_id` AS `customer_id`, `items`.`item_uom` AS `item_uom`, `items`.`uom_conversion` AS `uom_conversion`, `items`.`item_size` AS `item_size`, `items`.`item_amount` AS `item_amount`, `items`.`date_created` AS `date_created`, `items`.`status` AS `status`, `items`.`remove` AS `remove`, `items`.`last_update` AS `last_update` FROM `items` WHERE `items`.`item_type` = 'FG' AND `items`.`customer_id` is not null AND `items`.`customer_id` <> 0 ;

-- --------------------------------------------------------

--
-- Structure for view `view_inventory_status`
--
DROP TABLE IF EXISTS `view_inventory_status`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_inventory_status`  AS SELECT `i`.`item_id` AS `item_id`, `i`.`item_code` AS `item_code`, `i`.`item_description` AS `item_description`, `i`.`item_type` AS `item_type`, `i`.`item_uom` AS `item_uom`, `i`.`reorder_level` AS `reorder_level`, coalesce(sum(`ib`.`qty_on_hand`),0) AS `total_soh`, coalesce(sum(`ib`.`qty_allocated`),0) AS `total_allocated`, coalesce(sum(`ib`.`qty_on_hand`),0) - coalesce(sum(`ib`.`qty_allocated`),0) AS `available_stock`, CASE WHEN coalesce(sum(`ib`.`qty_on_hand`),0) - coalesce(sum(`ib`.`qty_allocated`),0) <= 0 THEN 'OUT OF STOCK' WHEN coalesce(sum(`ib`.`qty_on_hand`),0) - coalesce(sum(`ib`.`qty_allocated`),0) <= `i`.`reorder_level` THEN 'LOW STOCK' ELSE 'IN STOCK' END AS `inventory_status` FROM (`items` `i` left join `inventory_balances` `ib` on(`i`.`item_id` = `ib`.`item_id`)) GROUP BY `i`.`item_id` ;

-- --------------------------------------------------------

--
-- Structure for view `vw_lmr_available_stock`
--
DROP TABLE IF EXISTS `vw_lmr_available_stock`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_lmr_available_stock`  AS SELECT `inventory_stock`.`item_id` AS `item_id`, `inventory_stock`.`site_code` AS `site_code`, `inventory_stock`.`lot_number` AS `lot_number`, sum(`inventory_stock`.`qty_on_hand`) AS `available_qty`, max(`inventory_stock`.`updated_at`) AS `last_updated` FROM `inventory_stock` WHERE `inventory_stock`.`status` = 'PASSED' AND `inventory_stock`.`qty_on_hand` > 0 GROUP BY `inventory_stock`.`item_id`, `inventory_stock`.`site_code`, `inventory_stock`.`lot_number` ;

